23	/// An option value as stored in the catalog — the *index* in the values
24	/// array is the byte written into the patch binary.
25	enum OptionValue: Decodable, Sendable, Equatable, CustomStringConvertible {
26	    case text(String)
27	    case number(Double)
28	
29	    init(from decoder: Decoder) throws {
30	        let container = try decoder.singleValueContainer()
31	        if let s = try? container.decode(String.self) {
32	            self = .text(s)
33	        } else {
34	            self = .number(try container.decode(Double.self))
35	        }
36	    }
37	
38	    var description: String {
39	        switch self {
40	        case .text(let s): return s
41	        case .number(let n):
42	            return n == n.rounded() ? String(Int(n)) : String(n)
43	        }
44	    }
45	}
