166	        guard let index = modules.firstIndex(where: { $0.id == id }),
167	              optionIndex < 8 else { return }
168	        modules[index].optionBytes[optionIndex] = byte
169	        // Options change which blocks exist; the param list follows.
170	        let count = paramBlocks(of: modules[index]).count
171	        var params = modules[index].paramsRaw
172	        while params.count < count { params.append(0) }
173	        if params.count > count { params.removeLast(params.count - count) }
