import Foundation
import Testing
@testable import ZoiaCanvas

/// TEMPORARY — structural verification of the generated MIDI-to-CV patch.
/// Delete after use.
@Suite struct TempMidiCVVerifyTests {
    @Test func generatedPatchIsStructurallyValid() throws {
        let path = ProcessInfo.processInfo.environment["MIDICV_BIN"] ?? ""
        let data = try Data(contentsOf: URL(fileURLWithPath: path))
        let patch = try ZoiaPatchBinary.decode(data)
        let catalog = try ModuleCatalog.loadBundled()

        #expect(patch.name == "MIDI to CV")
        #expect(patch.modules.count == 12)
        #expect(patch.connections.count == 15)
        #expect(patch.pageNamesRaw.count == 2)

        // Active blocks and param counts per module.
        var active: [[BlockSpec]] = []
        for (i, m) in patch.modules.enumerated() {
            let spec = try #require(catalog[m.typeID], "module \(m.typeID) missing")
            let blocks = try BlockLayout.activeBlocks(
                spec: spec, optionBytes: m.optionBytes, version: m.version)
            active.append(blocks)
            let paramBlocks = blocks.filter { $0.isParam == true }
            #expect(m.paramsRaw.count == paramBlocks.count,
                    "module \(i) \(spec.name): \(m.paramsRaw.count) params vs \(paramBlocks.count) param blocks")
            print("MOD \(i) \(spec.name) page=\(m.pageRaw) pos=\(m.position) "
                  + "blocks=\(blocks.count) [\(blocks.map(\.key).joined(separator: ","))] "
                  + "params=\(m.paramsRaw)")
        }

        // Every cable endpoint must be an active block of the right direction.
        for (n, c) in patch.connections.enumerated() {
            let src = try #require(active[safe: c.sourceModule], "conn \(n) bad src module")
            let dst = try #require(active[safe: c.destModule], "conn \(n) bad dst module")
            let sBlock = src.first { ($0.position ?? -1) == c.sourceBlock }
            let dBlock = dst.first { ($0.position ?? -1) == c.destBlock }
            #expect(sBlock != nil, "conn \(n): source block \(c.sourceBlock) not active")
            #expect(dBlock != nil, "conn \(n): dest block \(c.destBlock) not active")
            #expect(sBlock?.type.isOutput == true, "conn \(n): source is not an output")
            #expect(dBlock?.type.isOutput == false, "conn \(n): dest is not an input")
        }

        // No two modules may overlap on a page's 40 buttons.
        var used: [Int: Set<Int>] = [:]
        for (i, m) in patch.modules.enumerated() {
            let span = active[i].count
            #expect(m.position + span <= 40, "module \(i) overruns page")
            for b in m.position..<(m.position + span) {
                #expect(used[m.pageRaw, default: []].contains(b) == false,
                        "module \(i) overlaps button \(b) on page \(m.pageRaw)")
                used[m.pageRaw, default: []].insert(b)
            }
        }

        // Re-encoding must be byte-identical to the file we generated.
        #expect(ZoiaPatchBinary.encode(patch) == data)
    }
}

